// Implement parseConfig according to this specification:
//
// Parse an INI-style config string into a nested object.
// Rules:
// 1. Lines are separated by '\n'.
// 2. Blank lines and lines starting with '#' (after trimming) are ignored.
// 3. Section headers look like '[sectionName]'. Keys before any section go into '__global__'.
// 4. Key-value lines are 'key = value'. Both key and value are trimmed.
// 5. If a section header is '[child:parent]', the child section INHERITS all keys from parent.
//    Explicitly set keys in the child override inherited ones.
// 6. Values that look like integers (match /^-?\d+$/) are converted to numbers.
// 7. Values 'true' and 'false' (case insensitive) are converted to booleans.
// 8. Duplicate keys within the same section: last value wins.
//
// Example:
//   '[base]\nport = 3000\n[dev:base]\ndebug = true'
//   => { __global__: {}, base: { port: 3000 }, dev: { port: 3000, debug: true } }

golden_completion:
function parseConfig(input: string): Record<string, Record<string, string | number | boolean>> {
    const res: Record<string, Record<string, any>> = { __global__: {} }, parents: Record<string, string> = {}; let cur = '__global__';
    for (const raw of input.split('\n')) {
        const ln = raw.trim(); if (!ln || ln.startsWith('#')) continue;
        const sm = ln.match(/^\[([^\]]+)\]$/); if (sm) { const p = sm[1].split(':'); cur = p[0].trim(); if (!res[cur]) res[cur] = {}; if (p.length > 1) parents[cur] = p[1].trim(); continue; }
        const eq = ln.indexOf('='); if (eq < 0) continue; const k = ln.slice(0, eq).trim(); let v: any = ln.slice(eq + 1).trim();
        if (/^-?\d+$/.test(v)) v = parseInt(v, 10); else if (v.toLowerCase() === 'true') v = true; else if (v.toLowerCase() === 'false') v = false;
        res[cur][k] = v;
    }
    for (const [c, p] of Object.entries(parents)) { if (res[p]) res[c] = { ...res[p], ...res[c] }; }
    return res;
}

