function memoizeWithTTL<A extends object, R>(
    fn: (arg: A) => R,
    ttlMs: number
): (arg: A) => R {
    const cache = new WeakMap<A, { value: R; expiry: number }>();
    return (arg: A): R => {
        const now = Date.now();
        if (cache.has(arg)) {
            const entry = cache.get(arg)!;
            if (now < entry.expiry) {
                return entry.value;
            }
        }
        const result = fn(arg);
        cache.set(arg, { value: result, expiry: now + ttlMs });
        return result;
    };
}

