function createRetrier(maxAttempts: number, baseDelayMs: number) {
    let attemptCount = 0;
    let lastDelay = 0;

    return {
        async attempt<T>(fn: () => Promise<T>): Promise<T> {
            attemptCount++;
            try {
                const result = await fn();
                attemptCount = 0;
                lastDelay = 0;
                return result;
            } catch (err) {
                if (attemptCount >= maxAttempts) {
                    attemptCount = 0;
                    lastDelay = 0;
                    throw err;
                }
                lastDelay = baseDelayMs * Math.pow(2, attemptCount - 1);
                await new Promise(r => setTimeout(r, lastDelay));
                return this.attempt(fn);
            }
        },
        getAttemptCount(): number { return attemptCount; },
        getLastDelay(): number { return lastDelay; },
    };
}

