class LazySeq<T> {
    constructor(private generator: () => Generator<T>) {}

    static from<U>(arr: U[]): LazySeq<U> {
        return new LazySeq(function* () { yield* arr; });
    }

    map<U>(fn: (item: T) => U): LazySeq<U> {
        const gen = this.generator;
        return new LazySeq(function* () {
            for (const item of gen()) {
                yield fn(item);
            }
        });
    }

    filter(pred: (item: T) => boolean): LazySeq<T> {
        const gen = this.generator;
        return new LazySeq(function* () {
            for (const item of gen()) {
                if (pred(item)) yield item;
            }
        });
    }

    take(n: number): T[] {
        const result: T[] = [];
        for (const item of this.generator()) {
            if (result.length >= n) break;
            result.push(item);
        }
        return result;
    }

    toArray(): T[] {
        return [...this.generator()];
    }
}

