map<U>(fn: (value: T) => U): Observable<U> {
    return new Observable<U>((obs) => this.subscribe({
        next: (v) => { try { obs.next(fn(v)); } catch (e) { obs.error(e as Error); } },
        error: (e) => obs.error(e), complete: () => obs.complete()
    }));
}
filter(predicate: (value: T) => boolean): Observable<T> {
    return new Observable<T>((obs) => this.subscribe({
        next: (v) => { try { if (predicate(v)) obs.next(v); } catch (e) { obs.error(e as Error); } },
        error: (e) => obs.error(e), complete: () => obs.complete()
    }));
}
take(n: number): Observable<T> {
    return new Observable<T>((obs) => {
        let count = 0; let unsub: Unsubscribe | undefined;
        unsub = this.subscribe({
            next: (v) => { if (count < n) { count++; obs.next(v); if (count === n) { obs.complete(); if (unsub) unsub(); } } },
            error: (e) => obs.error(e), complete: () => obs.complete()
        });
        return unsub;
    });
}

