// take calls complete and stops
const items: number[] = [];
let compCount = 0;
const infinite = new Observable<number>((obs) => {
    let i = 0;
    const id = setInterval(() => obs.next(i++), 1);
    return () => clearInterval(id);
});

// Synchronous source for reliable testing
const syncSource = new Observable<number>((obs) => {
    for (let i = 0; i < 100; i++) obs.next(i);
    obs.complete();
});

syncSource.take(5).subscribe({
    next: (v) => items.push(v),
    complete: () => compCount++
});
assert.deepStrictEqual(items, [0, 1, 2, 3, 4]);
assert.strictEqual(compCount, 1); // complete called exactly once

// map error propagation
let caughtErr: any = null;
source.map((x) => {
    if (x === 2) throw new Error('boom');
    return x;
}).subscribe({
    next: () => {},
    error: (e) => { caughtErr = e; }
});
assert.ok(caughtErr !== null);
assert.strictEqual((caughtErr as Error).message, 'boom');

// filter + take composition
const composed: number[] = [];
syncSource.filter(x => x % 2 === 0).take(3).subscribe({
    next: (v) => composed.push(v)
});
assert.deepStrictEqual(composed, [0, 2, 4]);

console.log('Task 49 assertions passed');

