// Valid object
const schema: SchemaType = {
    kind: 'object',
    properties: {
        name: { kind: 'string' },
        age: { kind: 'number' },
        active: { kind: 'boolean' }
    },
    required: ['name', 'age']
};

const errs1 = validateSchema({ name: 'Alice', age: 30 }, schema);
assert.strictEqual(errs1.length, 0);

// Missing required field
const errs2 = validateSchema({ name: 'Bob' }, schema);
assert.strictEqual(errs2.length, 1);
assert.strictEqual(errs2[0].path, '$.age');
assert.strictEqual(errs2[0].actual, 'missing');

// Wrong type
const errs3 = validateSchema({ name: 42, age: 'old' }, schema);
assert.strictEqual(errs3.length, 2);

console.log('Task 50 suffix passed');

