const doc50 = (validateSchema as any).doc;
assert.ok(doc50.includes('recursive') || doc50.includes('Recursive'), 'must mention recursive validation');
assert.ok(doc50.includes('NaN') || doc50.includes('nan'), 'must mention NaN rejection');
assert.ok(doc50.includes('JSONPath') || doc50.includes('path') || doc50.includes('$.'), 'must mention path format');
assert.ok(doc50.includes('required') && (doc50.includes('missing') || doc50.includes('absent')), 'must describe required/missing');
assert.ok(doc50.includes('optional') || doc50.includes('silently') || doc50.includes('skipped'), 'must describe optional fields');
assert.ok(doc50.includes('union') && (doc50.includes('ANY') || doc50.includes('any variant') || doc50.includes('one of')), 'must describe union semantics');
assert.ok(doc50.includes('empty array') || doc50.includes('no errors'), 'must mention empty array for valid');
assert.ok(doc50.includes('[') && doc50.includes('.'), 'must mention both bracket and dot notation in paths');

// Array validation with paths
const arrSchema: SchemaType = { kind: 'array', items: { kind: 'number' } };
const errs4 = validateSchema([1, 'two', 3], arrSchema);
assert.strictEqual(errs4.length, 1);
assert.strictEqual(errs4[0].path, '$[1]');

// Union type
const unionSchema: SchemaType = { kind: 'union', variants: [{ kind: 'string' }, { kind: 'number' }] };
assert.strictEqual(validateSchema('hello', unionSchema).length, 0);
assert.strictEqual(validateSchema(42, unionSchema).length, 0);
const unionErr = validateSchema(true, unionSchema);
assert.strictEqual(unionErr.length, 1);
assert.ok(unionErr[0].expected.includes('|'));

// NaN is invalid number
const nanErr = validateSchema(NaN, { kind: 'number' });
assert.strictEqual(nanErr.length, 1);
assert.strictEqual(nanErr[0].actual, 'NaN');

// Nested object path
const nestedSchema: SchemaType = {
    kind: 'object',
    properties: { data: { kind: 'object', properties: { id: { kind: 'number' } }, required: ['id'] } },
    required: ['data']
};
const errs5 = validateSchema({ data: { id: 'not-a-number' } }, nestedSchema);
assert.strictEqual(errs5[0].path, '$.data.id');

console.log('Task 50 assertions passed');
